""" Creates an ordered list from a list of tuples or other hashable items.
    From https://code.activestate.com/recipes/576694/#c6
    """
def unique_list(a_list: Any) -> object {
    m_map = {};
    o_set = [];
    for item in a_list {
        if (item not in m_map) {
            m_map[item] = 1;
            o_set.append(item);
        }
    }
    return o_set;
}

