"""
    Code referenced from http://code.activestate.com/recipes/52213-soundex-algorithm/

    @author: Pradnya Kulkarni

    """
def soundex(name: Any, len: Any = 4) -> object {
    digits = "01230120022455012623010202";
    sndx = "";
    fc = "";
    for c in name.upper() {
        if c.isalpha() {
            if not fc {
                fc = c;
            }
            d = digits[(ord(c) - ord("A"))];
            if (not sndx or (d != sndx[-1])) {
                sndx += d;
            }
        }
    }
    sndx = fc + sndx[1:];
    sndx = sndx.replace("0", "");
    return (sndx + (len * "0"))[:len];
}

"""Fail if the two objects are equal as determined by the '=='
       operator.
    """
def assert_not_equal(other: Any, `obj: Any, msg: Any = None) -> object {
    if (`obj == other) {
        raise AssertionError((msg or ('%r == %r' % (`obj, other))));
    }
    return `obj;
}
